500118.Script:
.@g = getenchantgrade();
.@r = getrefine();
.@max_lvl = min(250,BaseLevel);
bonus bUnbreakableWeapon;
bonus bMatk,300;
bonus bAspd,10;
skill "MG_FIREBOLT",10;
skill "SM_MAGNUM",10;
bonus2 bSkillAtk,"MG_FIREBOLT",10*.@max_lvl;
bonus2 bSkillAtk,"SM_MAGNUM",10*.@max_lvl;
bonus bPow,1*.@r;
bonus bSpl,1*.@r;
bonus2 bMagicAddClass,Class_All,12*.@r;
bonus2 bAddClass,Class_All,12*.@r;
if (.@r>=10) {
   bonus bAllStats,10;
   if (.@r>=11) {
      bonus bStr,25;
      bonus bInt,25;
      if (.@r>=12) {
         bonus3 bAutoSpell,"SM_MAGNUM",10,500;
         bonus3 bAutoSpell,"MG_FIREBOLT",10,500;
         if (.@r>=13) {
            bonus2 bMagicAddClass,Class_All,25;
            bonus2 bAddClass,Class_All,25;
            if (.@r>=14) {
               bonus2 bSkillAtk,"RK_IGNITIONBREAK",60;
               bonus2 bSkillAtk,"WL_CRIMSONROCK",60;
               if (.@r>=15) {
                  skill "MG_ENERGYCOAT",1;
                  bonus2 bMagicAddClass,Class_All,40;
                  bonus2 bAddClass,Class_All,40;
               }
            }
         }
      }
   }
}
if (.@g>=ENCHANTGRADE_D) {
   bonus bPow,5; bonus bSpl,5;
   if (.@g>=ENCHANTGRADE_C) {
      bonus2 bIgnoreDefRaceRate,RC_All,30;
      bonus2 bIgnoreMdefRaceRate,RC_All,30;
      if (.@g>=ENCHANTGRADE_B) {
         bonus bSMatk,10; bonus bPAtk,10;
         if (.@g>=ENCHANTGRADE_A) {
            bonus bNoWalkDelay;
         }
      }
   }
}

